package com.example.starter.quarantine.domain;

import java.time.Duration;

/**
 * 动物种类。有效期自出证时刻（UTC）起算：猪牛羊 24 小时，禽 48 小时。
 */
public enum AnimalType {

    PIG(Duration.ofHours(24)),
    CATTLE(Duration.ofHours(24)),
    SHEEP(Duration.ofHours(24)),
    POULTRY(Duration.ofHours(48));

    private final Duration certificateValidity;

    AnimalType(Duration certificateValidity) {
        this.certificateValidity = certificateValidity;
    }

    /**
     * @return 检疫合格证有效期（UTC）
     */
    public Duration certificateValidity() {
        return certificateValidity;
    }
}

package com.example.starter.quarantine.domain;

/**
 * 检疫申报单据状态。
 */
public enum RequestStatus {

    /** 已申报，等待产地检疫出证。 */
    SUBMITTED,
    /** 产地被划为疫点封锁区，未出证申报被驳回（终态）。 */
    REJECTED,
    /** 已出证但未启运时封锁发布，证被自动作废（终态）。 */
    VOID,
    /** 已出证，等待启运。 */
    CERTIFIED,
    /** 已启运，调运在途。 */
    IN_TRANSIT,
    /** 落地报告超过证有效期，证失效（终态）。 */
    EXPIRED,
    /** 落地累计数量等于证载数量，结案（终态）。 */
    CLOSED
}

package com.example.starter.quarantine.domain;

/**
 * 检疫合格证状态。
 */
public enum CertificateStatus {

    /** 有效（含在途）。 */
    VALID,
    /** 封锁发布时已出证未启运，证自动作废（终态）。 */
    VOID,
    /** 落地报告超时，证失效（终态）。 */
    EXPIRED,
    /** 证载动物全部落地，结案（终态）。 */
    CLOSED
}

package com.example.starter.quarantine.domain;

/**
 * 疫点封锁状态。
 */
public enum BlockadeStatus {

    /** 封锁生效中；发布即即刻生效。 */
    ACTIVE,
    /** 解除封锁（本题不涉及解除流程，预留）。 */
    RELEASED
}

package com.example.starter.quarantine.config;

import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时钟配置。业务时刻统一取自该 Clock（UTC），测试可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

