package com.example.starter.quarantine.support;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * 幂等指纹工具：对命令键与全部业务字段做 SHA-256。字段以 NUL 分隔，避免拼接歧义。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    public static String sha256(Object... parts) {
        MessageDigest digest;
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 不可用", ex);
        }
        for (Object part : parts) {
            digest.update(String.valueOf(part).getBytes(StandardCharsets.UTF_8));
            digest.update((byte) 0);
        }
        byte[] hash = digest.digest();
        StringBuilder hex = new StringBuilder(hash.length * 2);
        for (byte b : hash) {
            hex.append(String.format("%02x", b));
        }
        return hex.toString();
    }
}

package com.example.starter.quarantine.repository;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 养殖场仓储。{@link #lockFarm} 以 SELECT ... FOR UPDATE 持有农场行锁至事务结束，
 * 是同一养殖场上“出证/启运/落地/申报”与“封锁发布”之间的串行化点，保证封锁竞态唯一终态。
 */
@Repository
public class FarmRepository {

    private final JdbcTemplate jdbcTemplate;

    public FarmRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 锁定养殖场行并返回其是否存在。必须在事务内调用，锁持有到事务提交/回滚。
     */
    public boolean lockFarm(String farmId) {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(1) FROM farm WHERE farm_id = ? FOR UPDATE", Integer.class, farmId);
        return count != null && count > 0;
    }

    /** 取下一个证号序列值。 */
    public long nextCertificateSequence() {
        Long value = jdbcTemplate.queryForObject("VALUES(NEXTVAL(cert_no_seq))", Long.class);
        return value == null ? 0L : value;
    }
}

