    po.setOriginFarm(request.originFarm());
    po.setDestination(request.destination());
    po.setAnimalType(request.animalType());
    po.setEarTagRange(request.earTagRange());
    po.setQuantity(request.quantity());
    // 封锁即刻生效：封锁生效期间的新申报同样一律驳回。
